import React, { useState } from 'react';

const TradePanel = ({ symbol, price, onBuy, onSell, loading }) => {
    const [quantity, setQuantity] = useState(1);
    const [tradeType, setTradeType] = useState('BUY');

    const totalCost = price ? price * quantity : 0;

    return (
        <div style={{
            background: '#141b2b',
            padding: '20px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c'
        }}>
            <h3 style={{ marginBottom: '15px', color: '#e0e6ed' }}>📊 Trade</h3>
            
            <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
                <button
                    onClick={() => setTradeType('BUY')}
                    style={{
                        flex: 1,
                        padding: '10px',
                        background: tradeType === 'BUY' ? '#4CAF50' : '#1a2332',
                        color: 'white',
                        border: tradeType === 'BUY' ? '2px solid #4CAF50' : '1px solid #2a3a5c',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontWeight: 'bold'
                    }}
                >
                    BUY
                </button>
                <button
                    onClick={() => setTradeType('SELL')}
                    style={{
                        flex: 1,
                        padding: '10px',
                        background: tradeType === 'SELL' ? '#dc3545' : '#1a2332',
                        color: 'white',
                        border: tradeType === 'SELL' ? '2px solid #dc3545' : '1px solid #2a3a5c',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontWeight: 'bold'
                    }}
                >
                    SELL
                </button>
            </div>

            <div style={{ marginBottom: '15px' }}>
                <label style={{ display: 'block', marginBottom: '5px', color: '#8a9bb5' }}>
                    Quantity
                </label>
                <input
                    type="number"
                    min="1"
                    value={quantity}
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                    style={{
                        width: '100%',
                        padding: '10px',
                        background: '#1a2332',
                        border: '1px solid #2a3a5c',
                        borderRadius: '6px',
                        color: 'white',
                        fontSize: '16px'
                    }}
                />
            </div>

            {price && (
                <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    padding: '10px',
                    background: '#1a2332',
                    borderRadius: '6px',
                    marginBottom: '15px'
                }}>
                    <span style={{ color: '#8a9bb5' }}>Total Cost</span>
                    <span style={{ fontWeight: 'bold' }}>₹{totalCost.toFixed(2)}</span>
                </div>
            )}

            <button
                onClick={() => {
                    if (tradeType === 'BUY') {
                        onBuy(quantity);
                    } else {
                        onSell(quantity);
                    }
                }}
                disabled={loading || !price}
                style={{
                    width: '100%',
                    padding: '12px',
                    background: tradeType === 'BUY' ? '#4CAF50' : '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    fontSize: '16px',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    opacity: loading || !price ? 0.5 : 1
                }}
            >
                {loading ? 'Processing...' : `${tradeType} ${symbol}`}
            </button>

            {!price && (
                <p style={{ color: '#8a9bb5', textAlign: 'center', marginTop: '10px', fontSize: '14px' }}>
                    🔍 Search for a stock to start trading
                </p>
            )}
        </div>
    );
};

export default TradePanel;
